function EditUserModal({
  user,
  branches,
  users,
  currentUserId,
  onClose,
  onSaved
}: {
  user: AdminUser;
  branches: Branch[];
  users: AdminUser[];
  currentUserId: number;
  onClose: () => void;
  onSaved: () => void;
}) {
  const isOwner = user.role_code === "OWNER";
  const isSelf = user.id === currentUserId;
  const occupiedBranchIds = new Set(
    users.filter((item)=>item.id!==user.id && item.role_code==="CASHIER" && Boolean(item.active) && item.branch_id!=null).map((item)=>Number(item.branch_id))
  );
  const [branchId, setBranchId] = useState(user.branch_id ? String(user.branch_id) : "");
  const [fullName, setFullName] = useState(user.full_name);
  const [username, setUsername] = useState(user.username);
  const [active, setActive] = useState(Boolean(user.active));
  const [newPassword, setNewPassword] = useState("");
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");
  const [saving, setSaving] = useState(false);

  async function save(event: FormEvent) {
    event.preventDefault();
    setSaving(true); setError(""); setMessage("");
    try {
      await api(`/api/admin/users/${user.id}/update`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          roleCode: isOwner ? "OWNER" : "CASHIER",
          branchId: isOwner ? null : Number(branchId),
          fullName,
          username,
          active
        })
      });
      setMessage("Cuenta actualizada.");
      await onSaved();
    } catch (err) {
      setError(err instanceof Error ? err.message : "No se pudo actualizar la cuenta");
    } finally {
      setSaving(false);
    }
  }

  async function resetPassword() {
    setSaving(true); setError(""); setMessage("");
    try {
      await api(`/api/admin/users/${user.id}/reset-password`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ password: newPassword })
      });
      setNewPassword("");
      setMessage("ContraseÃ±a restablecida. Las sesiones anteriores fueron cerradas.");
    } catch (err) {
      setError(err instanceof Error ? err.message : "No se pudo restablecer la contraseÃ±a");
    } finally {
      setSaving(false);
    }
  }

  return <div className="modal-backdrop"><form className="modal" onSubmit={save}>
    <div className="modal-head"><div><h2>Editar cuenta</h2><p>{user.full_name} Â· @{user.username}</p></div><button type="button" className="icon-btn" onClick={onClose}><X size={18}/></button></div>
    <div className="field-grid">
      <label>Nombre completo<input value={fullName} onChange={(e)=>setFullName(e.target.value)} required /></label>
      <label>Nombre de la cuenta<input value={username} onChange={(e)=>setUsername(e.target.value)} required /></label>
    </div>
    <div className="field-grid">
      <label>Rol<select value={isOwner?"OWNER":"CASHIER"} disabled><option value="OWNER">Propietario</option><option value="CASHIER">Cajero / Encargado</option></select></label>
      <label>Filial<select value={branchId} onChange={(e)=>setBranchId(e.target.value)} disabled={isOwner}>{isOwner ? <option value="">Acceso global</option> : branches.map((branch)=><option value={branch.id} key={branch.id} disabled={occupiedBranchIds.has(branch.id)}>{branch.name}{occupiedBranchIds.has(branch.id)?" Â· ya tiene encargado":""}</option>)}</select></label>
    </div>
    <label className="active-toggle"><input type="checkbox" checked={active} onChange={(e)=>setActive(e.target.checked)} disabled={isSelf} /> Cuenta activa</label>
    <div className="password-reset-box">
      <div><KeyRound size={17}/><div><strong>Restablecer contraseÃ±a</strong><span>Cierra las demÃ¡s sesiones del usuario.</span></div></div>
      <div className="password-reset-row"><input type="password" value={newPassword} onChange={(e)=>setNewPassword(e.target.value)} placeholder="Nueva contraseÃ±a segura" /><button type="button" className="soft" disabled={saving || !newPassword} onClick={() => void resetPassword()}>Restablecer</button></div>
    </div>
    {error && <div className="modal-error">{error}</div>}
    {message && <div className="success-message">{message}</div>}
    <div className="modal-actions"><button type="button" className="ghost-button" onClick={onClose}>Cerrar</button><button className="primary" disabled={saving || (!isOwner && !branchId)}>{saving ? "Guardandoâ€¦" : "Guardar cuenta"}</button></div>
  </form></div>;
}

function BranchDetailModal({
  branchId,
  onClose,
  onChanged
}: {
  branchId: number;
  onClose: () => void;
  onChanged: () => Promise<void>;
}) {
  const [detail, setDetail] = useState<BranchDetail | null>(null);
  const [tab, setTab] = useState<"overview"|"operations"|"users"|"closures"|"electronic">("overview");
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");
  const [processingElectronicSources, setProcessingElectronicSources] = useState<Set<string>>(() => new Set());
  const processingElectronicSourcesRef = useRef(new Set<string>());
  const [code, setCode] = useState("");
  const [name, setName] = useState("");
  const [address, setAddress] = useState("");
  const [active, setActive] = useState(true);
  const [maxAmount, setMaxAmount] = useState("");
  const [commissionType, setCommissionType] = useState<"FLAT"|"PERCENT">("FLAT");
  const [commissionValue, setCommissionValue] = useState("");

  async function loadDetail() {
    setLoading(true); setError("");
    try {
      const [data, archives] = await Promise.all([
        api<BranchDetail>(`/api/admin/branches/${branchId}/detail`),
        api<{documents:ElectronicArchiveDocument[]}>(`/api/admin/branches/${branchId}/electronic-documents`)
      ]);
      setDetail({ ...data, electronicDocuments: archives.documents });
      setCode(data.branch.code);
      setName(data.branch.name);
      setAddress(data.branch.address ?? "");
      setActive(data.branch.active);
      setMaxAmount(String(data.branch.settings.maxOperationAmount));
      setCommissionType(data.branch.settings.commissionType);
      setCommissionValue(String(data.branch.settings.commissionValue));
    } catch (err) {
      setError(err instanceof Error ? err.message : "No se pudo cargar la filial");
    } finally {
      setLoading(false);
    }
  }

  async function retryElectronicDocuments(document: ElectronicArchiveDocument) {
    const sourceType = document.closure_id != null ? "closure" : "operation";
    const sourceId = document.closure_id ?? document.operation_id;
    if (sourceId == null) return;
    const requestKey = `${branchId}:${sourceType}:${sourceId}`;
    if (processingElectronicSourcesRef.current.has(requestKey)) return;
    processingElectronicSourcesRef.current.add(requestKey);
    setProcessingElectronicSources(new Set(processingElectronicSourcesRef.current));
    setError("");
    setMessage("");
    try {
      const result = await api<{ remaining: number; results: Array<{ status: string; message?: string }> }>(`/api/admin/branches/${branchId}/electronic-documents/${sourceType}/${sourceId}/process-pending`, { method: "POST" });
      const failed = result.results.find((item) => item.status === "ERROR");
      if (!failed) setMessage("Reintento enviado. Consultando la respuesta de ApiSunatâ€¦");
      await loadDetail();
      if (failed) setError(failed.message || "No se pudo enviar la boleta. Revisa los datos de ApiSunat.");
      else if (result.results.some((item) => item.status === "PENDING")) {
        let latestDocuments: ElectronicArchiveDocument[] = [];
        for (let attempt = 0; attempt < 10; attempt++) {
          await new Promise((resolve) => setTimeout(resolve, 3000));
          try {
            const archives = await api<{ documents: ElectronicArchiveDocument[] }>(`/api/admin/branches/${branchId}/electronic-documents`);
            latestDocuments = archives.documents;
            setDetail((current) => current ? { ...current, electronicDocuments: archives.documents } : current);
            const sourceDocuments = archives.documents.filter((item) => sourceType === "closure" ? item.closure_id === sourceId : item.operation_id === sourceId);
            if (sourceDocuments.length && sourceDocuments.every((item) => item.status !== "PENDING")) break;
          } catch { /* Keep checking; the next refresh can recover a temporary network error. */ }
        }
        const sourceDocuments = latestDocuments.filter((item) => sourceType === "closure" ? item.closure_id === sourceId : item.operation_id === sourceId);
        if (sourceDocuments.length && sourceDocuments.every((item) => item.status === "ACCEPTED")) {
          setMessage("Boleta aceptada por ApiSunat. PDF, XML y CDR guardados en el panel.");
        } else if (sourceDocuments.some((item) => item.status === "PENDING")) {
          setMessage("ApiSunat aÃºn estÃ¡ validando la boleta. El estado sigue visible en esta tabla.");
        } else if (sourceDocuments.some((item) => ["EXCEPTION", "REJECTED", "ERROR"].includes(item.status))) {
          setMessage("ApiSunat respondiÃ³ con una observaciÃ³n. Revisa el estado y el detalle en la tabla.");
        }
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "No se pudieron emitir las boletas pendientes.");
    } finally {
      processingElectronicSourcesRef.current.delete(requestKey);
      setProcessingElectronicSources(new Set(processingElectronicSourcesRef.current));
    }
  }

  useEffect(() => { void loadDetail(); }, [branchId]);

  // Refresh the administrator archive while ApiSunat is still validating documents.
  // Only the archive list is replaced; branch detail fields and the rest of the modal stay put.
  const hasDocumentsBeingValidated = (detail?.electronicDocuments ?? []).some((document) => document.status === "PENDING");
  useEffect(() => {
    if (tab !== "electronic" || !hasDocumentsBeingValidated) return;
    let active = true;
    let checking = false;
    const refreshElectronicDocuments = async () => {
      if (checking) return;
      checking = true;
      try {
        const archives = await api<{ documents: ElectronicArchiveDocument[] }>(`/api/admin/branches/${branchId}/electronic-documents`);
        if (active) setDetail((current) => current ? { ...current, electronicDocuments: archives.documents } : current);
      } catch { /* Retry on the next interval after a temporary network issue. */ }
      finally { checking = false; }
    };
    const timer = window.setInterval(() => { void refreshElectronicDocuments(); }, 4000);
    return () => { active = false; window.clearInterval(timer); };
  }, [branchId, tab, hasDocumentsBeingValidated]);

  async function saveBranch(event: FormEvent) {
    event.preventDefault(); setSaving(true); setError(""); setMessage("");
    try {
      await api(`/api/admin/branches/${branchId}/update`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ code, name, address: address || null, active })
      });
      await api(`/api/admin/branches/${branchId}/settings`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          maxOperationAmount: Number(maxAmount),
          commissionType,
          commissionValue: Number(commissionValue)
        })
      });
      setMessage("Filial actualizada correctamente.");
      await Promise.all([loadDetail(), onChanged()]);
    } catch (err) {
      setError(err instanceof Error ? err.message : "No se pudo guardar la filial");
    } finally {
      setSaving(false);
    }
  }

  return <div className="modal-backdrop branch-detail-backdrop">
    <div className="branch-detail-modal">
      <div className="branch-detail-header">
        <div>
          <div className="branch-detail-title"><div className="branch-monogram big">{detail?.branch.code.slice(0,2) ?? "--"}</div><div><h2>{detail?.branch.name ?? "Filial"}</h2><span>{detail?.branch.code ?? ""} Â· {detail?.branch.active ? "Activa" : "Inactiva"}</span></div></div>
          <p>{detail?.branch.address ?? "Sin direcciÃ³n registrada"}</p>
        </div>
        <button className="icon-btn" onClick={onClose}><X size={19}/></button>
      </div>

      <div className="branch-detail-tabs">
        <button className={tab==="overview"?"active":""} onClick={()=>setTab("overview")}>Resumen</button>
        <button className={tab==="operations"?"active":""} onClick={()=>setTab("operations")}>Operaciones</button>
        <button className={tab==="users"?"active":""} onClick={()=>setTab("users")}>Usuarios</button>
        <button className={tab==="closures"?"active":""} onClick={()=>setTab("closures")}>Cierres</button>
        <button className={tab==="electronic"?"active":""} onClick={()=>setTab("electronic")}>Boletas electrÃ³nicas</button>
      </div>

      {loading && <div className="branch-detail-loading">Cargando filialâ€¦</div>}
      {error && <div className="modal-error branch-detail-error">{error}</div>}
      {message && tab === "electronic" && <div className="success-banner branch-detail-success">{message}</div>}

      {!loading && detail && tab==="overview" && <div className="branch-detail-body">
        <div className="branch-detail-kpis">
          <div><span>Operaciones hoy</span><strong>{detail.today.operations}</strong></div>
          <div><span>Monto movilizado hoy</span><strong>{currency(detail.today.amount)}</strong></div>
          <div><span>ComisiÃ³n hoy</span><strong>{currency(detail.today.commission)}</strong></div>
          <div><span>Usuarios asignados</span><strong>{detail.users.length}</strong></div>
          <div><span>Estado de caja</span><strong className={detail.cashSessions[0]?.status==="OPEN"?"green-text":"red-text"}>{detail.cashSessions[0]?.status==="OPEN"?"ABIERTA":"CERRADA"}</strong></div>
        </div>

        <form className="branch-detail-form card" onSubmit={saveBranch}>
          <div className="card-head"><div><strong>Datos y configuraciÃ³n</strong><span>Edita la filial sin salir de su ficha</span></div><Pencil size={16}/></div>
          <div className="branch-form-content">
            <div className="field-grid"><label>CÃ³digo<input value={code} onChange={(e)=>setCode(e.target.value)} required /></label><label>Nombre<input value={name} onChange={(e)=>setName(e.target.value)} required /></label></div>
            <label>DirecciÃ³n<input value={address} onChange={(e)=>setAddress(e.target.value)} /></label>
            <label className="active-toggle"><input type="checkbox" checked={active} onChange={(e)=>setActive(e.target.checked)} /> Filial activa</label>
            <div className="section-divider">Regla de operaciÃ³n</div>
            <div className="field-grid"><label>LÃ­mite por operaciÃ³n<div className="input-prefix"><span>S/</span><input value={maxAmount} onChange={(e)=>setMaxAmount(e.target.value)} required /></div></label><label>Tipo de comisiÃ³n<select value={commissionType} onChange={(e)=>setCommissionType(e.target.value as "FLAT"|"PERCENT")}><option value="FLAT">Monto fijo</option><option value="PERCENT">Porcentaje</option></select></label></div>
            <label>ComisiÃ³n del encargado<div className="input-prefix"><span>{commissionType==="FLAT"?"S/":"%"}</span><input value={commissionValue} onChange={(e)=>setCommissionValue(e.target.value)} required /></div></label>
            <div className="friendly-info"><UserCog size={16}/><span>Esta comisiÃ³n pertenece al encargado asignado a la filial.</span></div>
            {message && <div className="success-message">{message}</div>}
            <div className="modal-actions"><button className="primary" disabled={saving}>{saving?"Guardandoâ€¦":"Guardar cambios"}</button></div>
          </div>
        </form>

        <section className="card branch-live-card">
          <div className="card-head"><div><strong>Turnos de caja recientes</strong><span>Ãšltimos {detail.cashSessions.length}</span></div></div>
          <div className="branch-mini-list">
            {detail.cashSessions.slice(0,5).map((item)=><div key={item.id}><span className={item.status==="OPEN"?"branch-status open":"branch-status closed"}>{item.status==="OPEN"?"ABIERTA":"CERRADA"}</span><div><strong>{dateTime(item.started_at)}</strong><span>Inicial: {currency(item.initial_cash)} efectivo Â· {currency(item.initial_wallet)} Yape</span></div></div>)}
            {!detail.cashSessions.length && <div className="empty-cell">Sin turnos.</div>}
          </div>
        </section>
      </div>}

      {!loading && detail && tab==="operations" && <div className="branch-detail-table"><div className="table-wrap"><table className="admin-table"><thead><tr><th>Fecha</th><th>Tipo</th><th>Cliente</th><th>Referencia</th><th>Monto</th><th>ComisiÃ³n</th><th>Entregado</th><th>RegistrÃ³</th><th>Estado</th></tr></thead><tbody>
        {detail.recentOperations.map((op)=><tr key={op.id}><td>{dateTime(op.created_at)}</td><td><span className={`type-pill ${op.operation_type==="YAPE_TO_CASH"?"yape":"cash"}`}>{op.operation_type==="YAPE_TO_CASH"?"Yape â†’ Efectivo":"Efectivo â†’ Yape"}</span></td><td>{op.customer_name??"â€”"}</td><td>{op.reference_code??"â€”"}</td><td>{currency(op.amount)}</td><td>{currency(op.commission)}</td><td>{currency(op.net_amount)}</td><td>{op.registered_by??"â€”"}</td><td><span className={`status ${op.status==="COMPLETED"?"ok":"pending"}`}><i />{op.status==="COMPLETED"?"Completada":op.status==="IN_PROGRESS"?"En proceso":op.status==="CANCELLED"?"Anulada":op.status==="REVERSED"?"Revertida":op.status}</span></td></tr>)}
        {!detail.recentOperations.length && <tr><td colSpan={9} className="empty-cell">Sin operaciones.</td></tr>}
      </tbody></table></div></div>}

      {!loading && detail && tab==="users" && <div className="branch-detail-table"><div className="table-wrap"><table className="admin-table"><thead><tr><th>Nombre</th><th>Usuario</th><th>Rol</th><th>Ãšltimo acceso</th><th>Estado</th></tr></thead><tbody>
        {detail.users.map((item)=><tr key={item.id}><td><strong>{item.full_name}</strong></td><td>{item.username}</td><td>{item.role_name}</td><td>{dateTime(item.last_login_at)}</td><td><span className={item.active?"branch-status open":"branch-status closed"}>{item.active?"Activo":"Inactivo"}</span></td></tr>)}
        {!detail.users.length && <tr><td colSpan={5} className="empty-cell">No hay usuarios asignados.</td></tr>}
      </tbody></table></div></div>}

      {!loading && detail && tab==="closures" && <div className="branch-detail-table"><div className="table-wrap"><table className="admin-table"><thead><tr><th>Fecha</th><th>Resultado</th><th>Operaciones</th><th>ComisiÃ³n</th><th>Diferencias</th><th>PDF</th></tr></thead><tbody>
        {detail.closures.map((item)=><tr key={item.id}><td>{dateTime(item.closed_at)}</td><td><span className={`branch-status ${closureResult(item as Closure).cls}`}>{closureResult(item as Closure).label}</span></td><td>{item.operation_count ?? 0}</td><td><strong>{currency(item.commission_total)}</strong><br/><small>Ganancia del encargado</small></td><td><span className={Math.abs(Number(item.difference_cash))<0.005?"green-text":"red-text"}>Efectivo {currency(item.difference_cash)}</span><br/><span className={Math.abs(Number(item.difference_wallet))<0.005?"green-text":"red-text"}>Yape {currency(item.difference_wallet)}</span></td><td><button className="mini-button" onClick={()=>window.open(`/api/branches/${detail.branch.id}/closures/${item.id}/pdf`,"_blank")}><Download size={12}/> PDF</button></td></tr>)}
        {!detail.closures.length && <tr><td colSpan={6} className="empty-cell">TodavÃ­a no hay cierres.</td></tr>}
      </tbody></table></div></div>}

      {!loading && detail && tab==="electronic" && <div className="branch-detail-table"><div className="table-wrap"><table className="admin-table"><thead><tr><th>Fecha</th><th>Origen</th><th>Boleta</th><th>Parte</th><th>Importe</th><th>Estado</th><th>Archivos</th></tr></thead><tbody>
        {(detail.electronicDocuments ?? []).map((document)=>{const sourceType=document.closure_id != null ? "closure" : "operation";const sourceId=document.closure_id ?? document.operation_id;const requestKey=`${branchId}:${sourceType}:${sourceId}`;const processing=processingElectronicSources.has(requestKey);const displayedMessage=document.provider_message === "Pendiente de emisiÃ³n por el tope configurado." ? "En espera de reintento; revisa la conexiÃ³n y los datos fiscales." : electronicStatusMessage(document.status, document.provider_message);return <tr key={`${document.legacy ? "legacy" : "current"}-${document.id}`}><td>{dateTime(document.created_at)}</td><td>{document.closure_id ? `Cierre #${document.closure_id}` : `OperaciÃ³n #${document.operation_id}`}</td><td><strong>{document.series}{document.correlativo ? `-${String(document.correlativo).padStart(document.legacy ? 6 : 8,"0")}` : " Â· pendiente"}</strong></td><td>{document.part_number}/{document.part_count}</td><td>{currency(document.amount)}</td><td><span className={`electronic-status ${electronicStatusClass(document.status)}`}>{electronicStatusLabel(document.status)}</span><small className="closure-event-reason">{displayedMessage}</small></td><td className="closure-actions">{(["pdf","xml"] as const).map((format)=><button key={format} className={`mini-button${document.storedFiles?.[format] ? " electronic-action-ready" : ""}`} disabled={!document.storedFiles?.[format]} onClick={()=>window.open(document.legacy && document.closure_id ? `/api/branches/${detail.branch.id}/closures/${document.closure_id}/electronic-document/${format}` : `/api/branches/${detail.branch.id}/electronic-documents/${document.id}/${format}`,"_blank")}>{format === "pdf" ? <Eye size={12}/> : <Download size={12}/>} {format.toUpperCase()}</button>)}{document.canRetry && <button className={`mini-button${processing ? "" : " electronic-action-ready"}`} disabled={processing || sourceId == null} onClick={()=>void retryElectronicDocuments(document)}><RefreshCw size={12} className={processing ? "electronic-action-spinner" : undefined}/> {processing ? "Emitiendoâ€¦" : document.status === "QUEUED" ? "Emitir pendientes" : "Reintentar emisiÃ³n"}</button>}</td></tr>})}
        {!detail.electronicDocuments?.length && <tr><td colSpan={7} className="empty-cell">Esta filial todavÃ­a no tiene boletas electrÃ³nicas archivadas.</td></tr>}
      </tbody></table></div></div>}
    </div>
  </div>;
}
